query SlowOccurrenceKey($key: ID!, $language: String!, $defaultChecklistKey: ID) {
  occurrence(key: $key) {
    key
    localContexts {
      project_page
      title
      notice {
        name(lang: $language)
        img_url
      }
      labels {
        name(lang: $language)
        img_url
        communityName
      }
    }
    institution {
      name
    }
    collection {
      name
    }

    classification(checklistKey: $defaultChecklistKey) {
      vernacularNames(lang: $language, maxLimit: 1) {
        name
        reference {
          id
          citation
        }
      }
    }
  }
}
